from pathlib import Path
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4, landscape
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak

out=Path('output/pdf/E1_2_Registrations_Completion_Rules.pdf');out.parent.mkdir(parents=True,exist_ok=True)
navy=colors.HexColor('#132E57');blue=colors.HexColor('#3568BF');muted=colors.HexColor('#596E8F');line=colors.HexColor('#CCD9EE')
green=colors.HexColor('#2F6E46');greenbg=colors.HexColor('#E7F5EB');amber=colors.HexColor('#8A6411');amberbg=colors.HexColor('#FFF5D8');red=colors.HexColor('#9B2C2C');redbg=colors.HexColor('#FCECEC')
s=getSampleStyleSheet();s.add(ParagraphStyle(name='TitleX',parent=s['Title'],fontName='Helvetica-Bold',fontSize=19,leading=23,textColor=navy,spaceAfter=4));s.add(ParagraphStyle(name='Sub',parent=s['Normal'],fontSize=9,leading=12,textColor=muted));s.add(ParagraphStyle(name='H2X',parent=s['Heading2'],fontName='Helvetica-Bold',fontSize=12,leading=15,textColor=navy,spaceBefore=8,spaceAfter=5));s.add(ParagraphStyle(name='Cell',parent=s['Normal'],fontSize=8,leading=10.5,textColor=navy));s.add(ParagraphStyle(name='CellC',parent=s['Cell'],alignment=TA_CENTER,fontName='Helvetica-Bold'));s.add(ParagraphStyle(name='Head',parent=s['Cell'],fontName='Helvetica-Bold',textColor=colors.white,alignment=TA_CENTER));P=lambda x,st='Cell':Paragraph(x,s[st])
def table(data,widths,rag=False):
 t=Table(data,colWidths=widths,repeatRows=1);cmd=[('BACKGROUND',(0,0),(-1,0),navy),('GRID',(0,0),(-1,-1),.5,line),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6),('ROWBACKGROUNDS',(1,1),(-1,-1),[colors.white,colors.HexColor('#F7F9FC')])]
 if rag:cmd += [('BACKGROUND',(0,1),(0,1),greenbg),('TEXTCOLOR',(0,1),(0,1),green),('BACKGROUND',(0,2),(0,2),amberbg),('TEXTCOLOR',(0,2),(0,2),amber),('BACKGROUND',(0,3),(0,3),redbg),('TEXTCOLOR',(0,3),(0,3),red)]
 t.setStyle(TableStyle(cmd));return t
def footer(c,d):
 c.saveState();c.setFillColor(blue);c.rect(0,A4[0]-10,A4[1],10,fill=1,stroke=0);c.setStrokeColor(line);c.line(15*mm,10*mm,282*mm,10*mm);c.setFillColor(muted);c.setFont('Helvetica',7);c.drawString(15*mm,6*mm,'Carrier Configuration - E1.2 Completion Rules');c.drawRightString(282*mm,6*mm,f'Page {d.page}');c.restoreState()
doc=SimpleDocTemplate(str(out),pagesize=landscape(A4),rightMargin=15*mm,leftMargin=15*mm,topMargin=13*mm,bottomMargin=14*mm,title='E1.2 Registrations Completion Rules')
story=[P('E1.2 REGISTRATIONS','TitleX'),P('AHM565 Sheet E1.2 - Configuration Completion Rule Matrix','Sub'),Spacer(1,5*mm),P('Scope','H2X'),P('E1.2 records the Standard Fleet Weight and Standard Fleet Index for the carrier aircraft type and series/sub-type, plus the applicable starting weight and index for each physical aircraft registration. The larger AHM565 crew and pantry code build-up table is outside the scope of this page.'),Spacer(1,3*mm)]
sections=[[P('SECTION','Head'),P('CONFIGURED RULE','Head'),P('PARTIAL RULE','Head'),P('INCOMPLETE RULE','Head')],[P('1(a). Standard Fleet Values'),P('Standard Fleet Weight and Standard Fleet Index are both supplied and valid.'),P('Only one of the two required values is supplied.'),P('Neither value is supplied.')],[P('1(b). Aircraft Registrations'),P('At least one registration row contains a valid registration, applicable weight and applicable index.'),P('At least one registration has been entered, but no row is complete.'),P('No registration row exists.')]]
story += [table(sections,[170,235,210,170]),Spacer(1,5*mm),P('Page status matrix','H2X')]
status=[[P('STATUS','Head'),P('SECTION 1(a)','Head'),P('SECTION 1(b)','Head'),P('PAGE RESULT','Head')],[P('CONFIGURED','CellC'),P('CONFIGURED'),P('CONFIGURED'),P('CONFIGURED')],[P('PARTIALLY CONFIGURED','CellC'),P('PARTIAL or CONFIGURED'),P('At least one section is PARTIAL or CONFIGURED, but both are not CONFIGURED.'),P('PARTIALLY CONFIGURED')],[P('NOT CONFIGURED','CellC'),P('INCOMPLETE'),P('INCOMPLETE'),P('NOT CONFIGURED')]]
story += [table(status,[155,185,300,145],True),PageBreak(),P('E1.2 DATA AND CONTROL RULES','TitleX'),P('Field behaviour, persistence and fleet-data separation','Sub'),Spacer(1,5*mm)]
rules=[[P('ITEM','Head'),P('RULE','Head'),P('STORAGE / DISPLAY','Head')],[P('Standard Fleet Weight'),P('Nullable while work is in progress; when supplied it must be greater than zero. Displayed in KG.'),P('Basic_Aircraft_Data.Standard_Fleet_Weight.')],[P('Standard Fleet Index'),P('Nullable while work is in progress; when supplied it must be a finite numeric value.'),P('Basic_Aircraft_Data.Standard_Fleet_Index.')],[P('Aircraft Registration'),P('Required on every saved registration row; 1-10 uppercase letters, numbers or hyphens; unique for the carrier aircraft type and series/sub-type.'),P('Carrier_Aircraft_Fleet.Aircraft_Registration.')],[P('Applicable Weight and Index'),P('Labels and storage follow the E1.1 Start Weight Principle. Basic Weight uses Basic_Weight / Basic_Index. Dry Operating Weight uses Dry_Operating_Weight / Dry_Operating_Index.'),P('Carrier_Aircraft_Fleet; the non-applicable pair remains NULL on the registration reference row.')],[P('Registration reference row'),P('Maintained separately from crew/pantry-specific fleet rows. Existing detailed combinations are preserved. Initial migration uses the lightest existing weight/index pair only to initialise the reference.'),P('Carrier_Aircraft_Fleet.E1_2_Registration_Reference = TRUE, with Crew Code and Pantry Code NULL.')],[P('Crew and pantry combinations'),P('Not displayed or edited by E1.2. They remain available for later fleet-weight processing.'),P('Existing non-reference Carrier_Aircraft_Fleet rows remain unchanged.')],[P('E5 dependency'),P('E5 must revisit whether the registration reference is independently maintained or derived from a nominated crew/pantry combination, and define consistency controls.'),P('Recorded as an explicit E5 design reminder.')],[P('Global controls'),P('EDIT enters edit mode. ADD REGISTRATION creates a row. REMOVE removes only the registration reference. SAVE validates and persists atomically. CANCEL discards edits. The completion badge remains furthest right.'),P('Applied independently to both E1.2 subsections.')]]
story += [table(rules,[175,350,260])]
doc.build(story,onFirstPage=footer,onLaterPages=footer);print(out)
